use std::fs::File;
use std::io::{BufRead, BufReader, Write};
use std::sync::mpsc;
use std::thread;
use std::time::{Duration, Instant};

fn t0() -> Instant { Instant::now() }

fn reader(port: &'static str, tx: mpsc::Sender<(f64, String, String)>) {
    loop {
        match File::open(format!("/dev/robot/{}", port)) {
            Ok(f) => {
                let mut r = BufReader::new(f);
                let mut line = String::new();
                match r.read_line(&mut line) {
                    Ok(0) => {},
                    Ok(_) => { let _ = tx.send((t0().elapsed().as_secs_f64(), port.to_string(), line.trim().to_string())); },
                    Err(_) => {},
                }
            }
            Err(_) => thread::sleep(Duration::from_millis(50)),
        }
    }
}

fn w(port: &str, val: &str, log: &mut Vec<(f64,String,String)>, start: Instant) {
    if let Ok(mut f) = File::create(format!("/dev/robot/{}", port)) {
        let _ = writeln!(f, "{}", val);
        log.push((start.elapsed().as_secs_f64(), format!("W{}", port), val.to_string()));
    }
}

fn main() {
    let ports = ["d0","d2","d3","d4","d5","d6","d9","d11"];
    let (tx, rx) = mpsc::channel();
    for p in ports { let tx = tx.clone(); thread::spawn(move || reader(p, tx)); }
    let start = t0();
    let mut log: Vec<(f64,String,String)> = Vec::new();

    // Script: coast, forward, coast, turn?, both, coast
    w("d1","0",&mut log,start); w("d7","0",&mut log,start);
    thread::sleep(Duration::from_millis(1500));
    w("d1","2",&mut log,start);
    thread::sleep(Duration::from_millis(2000));
    w("d1","0",&mut log,start);
    thread::sleep(Duration::from_millis(1500));
    w("d7","2",&mut log,start);
    thread::sleep(Duration::from_millis(2000));
    w("d7","0",&mut log,start);
    thread::sleep(Duration::from_millis(1500));
    w("d1","2",&mut log,start); w("d7","-2",&mut log,start);
    thread::sleep(Duration::from_millis(2000));
    w("d1","0",&mut log,start); w("d7","0",&mut log,start);
    thread::sleep(Duration::from_millis(1500));

    while let Ok((t,p,l)) = rx.try_recv() { log.push((t,p,l)); }
    let _ = rx.try_recv();
    // drain a bit more
    let end = start.elapsed().as_secs_f64();
    while start.elapsed().as_secs_f64() < end + 0.2 {
        if let Ok((t,p,l)) = rx.try_recv() { log.push((t,p,l)); }
    }
    log.sort_by_key(|k| (k.0*1000.0) as i64);
    let mut out = File::create("/tmp/probe.log").unwrap();
    for (t,p,l) in log { writeln!(out, "{:.3} {} {}", t, p, l).unwrap(); }
    println!("done {} lines", log.len());
}
EOF
