import collections, statistics
data = collections.defaultdict(list)
for line in open('/tmp/probe.log'):
    p = line.split()
    if len(p) >= 3: data[p[1]].append((float(p[0]), ' '.join(p[2:])))
def rays(a,b):
    rows=[[float(x) for x in v.split(',')] for t,v in data['d2'] if a<=t<b]
    if not rows: return None
    return [round(statistics.mean(r[i] for r in rows),2) for i in range(16)]
base = rays(0.5,2.0)
print("base      :", base)
def shift(p1, p2):
    # shift s: p2[i] ~ p1[(i - s) % 16]; find s minimizing L1
    best=(1e9,0)
    for s in range(-8,9):
        l1=sum(abs(p2[i]-p1[(i-s)%16]) for i in range(16))
        if l1<best[0]: best=(l1,s)
    return best[1]
for a,b,nm in [(3.3,4.7,'spin(20,-20)'),(6.0,7.4,'spin(-20,20)'),(9.1,10.4,'fwd(20,20)'),(12.1,13.0,'back(-20,-20)')]:
    r=rays(a,b)
    if r:
        s=shift(base,r)
        closure=[round(r[i]-base[i],2) for i in range(16)]
        print(f"{nm}: shift={s:+d} rays:", r)
        print(f"   delta vs base: {closure}")
def head(a,b):
    vals=[float(v) for t,v in data['d4'] if a<=t<b]
    return f"{min(vals):.0f}-{max(vals):.0f}" if vals else "?"
for a,b,nm in [(3.3,4.7,'spinA'),(6.0,7.4,'spinB'),(9.1,10.4,'fwd'),(12.1,13.0,'back')]:
    print(nm, "d4:", head(a,b))
EOF

