            run(-20.0, -20.0, leg);
            if !v.is_nan() { results.push((target, v - best_d11, h_after)); }
            evlog("PROBE", &format!("abs={:.0} dd={:.4} hAfter={:.1}", target, v - best_d11, h_after));
