cd /bot/src/climb && python3 - <<'EOF'
s=open('main.rs').read()
i=s.index('fn main() {')
ridge='''fn main() {
    evlog("RIDGE", "greedy crest walker begin");
    let mut cur = sample_d11();
    let mut leg: u64 = 1200;
    let dirs = [0i64, 45, -45, 90, -90, 135, -135, 180];
    let mut stall = 0;
    loop {
        if at_goal() {
            evlog("GOAL", "flag fired - holding");
            loop { stop(); radio("A1 ATGOAL holding - R1 come!"); 
                   if let Some(m) = read_str("d10") { evlog("RX", &m); }
                   thread::sleep(Duration::from_millis(700)); }
        }
        if let Some(m) = read_str("d10") { evlog("RX", &m); }
        // escape if pinned
        let lid = read_lidar();
        let fm = (3..=8).map(|i| lid[i]).fold(f64::INFINITY, f64::min);
        if fm < 0.3 {
            evlog("ESC", &format!("front={:.2}", fm));
            run(-20.0, -20.0, 1000);
            let h = heading().unwrap_or(0.0);
            spin_to(norm(h + 60.0));
            continue;
        }
        let h0 = heading().unwrap_or(0.0);
