        for &d in dirs.iter() {
            spin_to(norm(h0 + d as f64));
            run(20.0, 20.0, leg);
            let v = sample_d11();
            evlog("TRY", &format!("rel={} d11={:.4} (cur {:.4})", d, v, cur));
            if !v.is_nan() && !cur.is_nan() && v > cur + 0.002 {
                cur = v;
                moved = true;
                stall = 0;
                break; // keep going in this direction
            }
            // walk back? no - just try next direction from new spot
        }
        if !moved {
            stall += 1;
            // all directions failed from here; try longer probe straight
            run(20.0, 20.0, leg * 3);
            let v = sample_d11();
            evlog("LONG", &format!("d11={:.4}", v));
            if !v.is_nan() && !cur.is_nan() && v > cur { cur = v; stall = 0; }
            if stall >= 2 {
                radio(&format!("A1 on d11 shelf {:.3}, searching crest", cur));
                spin_to(norm(heading().unwrap_or(0.0) + 90.0));
                stall = 0;
            }
        }
        radio(&format!("A1 ridge d11={:.3}", cur));
    }
}
